package org.sleepwell.app;

import android.app.*;
import android.content.DialogInterface;
import android.os.Bundle;
import android.graphics.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;

/** Board 08 history and calendar-based trends, backed by saved effective records. */
public final class HistoryActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private List<RecordEntry> records=List.of();private Map<Long,List<org.json.JSONObject>> measurements=Map.of();private boolean loaded,trends,searching,anchorChosen;private String query="",filter="All",failure="";private LocalDate day,anchor=LocalDate.now();private int period,generation;private long selected;
    private DatedGoalBank.Summary[] bankSummaries;private LocalDate bankAnchor;private String goalFailure="";
    private LinearLayout list;private TextView helper;private Dialog optionsDialog;private RecordCalendar calendar;private String calendarPurpose;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);trends=getIntent().getBooleanExtra("trends",false);if(state!=null){anchorChosen=true;trends=state.getBoolean("trends");searching=state.getBoolean("searching");query=state.getString("query","");filter=state.getString("filter","All");period=state.getInt("period");selected=state.getLong("selected");anchor=LocalDate.parse(state.getString("anchor",LocalDate.now().toString()));String date=state.getString("day");if(date!=null)day=LocalDate.parse(date);}render();if(state!=null&&state.containsKey("calendarPurpose"))openCalendar(state.getString("calendarPurpose"),state.getBundle("calendarState"));}
    @Override protected void onResume(){super.onResume();load();}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("trends",trends);state.putBoolean("searching",searching);state.putString("query",query);state.putString("filter",filter);state.putInt("period",period);state.putLong("selected",selected);state.putString("anchor",anchor.toString());if(day!=null)state.putString("day",day.toString());if(calendar!=null&&calendar.showing()){state.putString("calendarPurpose",calendarPurpose);state.putBundle("calendarState",calendar.state());}}
    private int cutoff(){return Math.max(0,Math.min(1439,Prefs.number(this,"statsCutoff",0)));}
    private long goal(){return Math.max(1,SleepPlans.load(this).goal)*60000L;}
    private void load(){int request=++generation;LocalDate requestedAnchor=anchor;boolean chooseLatest=!loaded&&!anchorChosen;int requestedCutoff=cutoff();Records.Factory factory=Records.factory;SleepPlans.Repository plans=SleepPlans.repository(this);worker.execute(()->{try(Store store=factory.open(getApplicationContext())){List<RecordEntry> entries=Records.all(store);Map<Long,List<org.json.JSONObject>> readings=new HashMap<>();
        // Only recent rows need miniature signal ribbons; older rows still show true coverage.
        for(int n=0;n<Math.min(60,entries.size());n++){RecordEntry entry=entries.get(n);if(!entry.manual())readings.put(entry.id,store.rows("SELECT start,time,movement FROM epochs WHERE session=? ORDER BY time",""+entry.id));}
        List<GoalCommitment> goals;String goalError;try{goals=plans.goals();goalError="";}catch(Exception e){goals=List.of();goalError="Goal history needs attention";}LocalDate effectiveAnchor=chooseLatest&&!entries.isEmpty()?entries.stream().map(r->r.day(requestedCutoff)).max(LocalDate::compareTo).orElse(requestedAnchor):requestedAnchor;DatedGoalBank calculated=new DatedGoalBank(goals,entries,Instant.now());DatedGoalBank.Summary[] summaries=new DatedGoalBank.Summary[3];for(int n=0;n<3;n++)summaries[n]=calculated.summary(RecordTrends.range(effectiveAnchor,n));String savedGoalError=goalError;
        runOnUiThread(()->{if(isDestroyed()||request!=generation)return;bankSummaries=summaries;bankAnchor=effectiveAnchor;goalFailure=savedGoalError;records=entries;measurements=readings;if(chooseLatest)anchor=effectiveAnchor;loaded=true;failure="";render();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;failure="Your sleep records could not be opened.";render();});}});}
    private void render(){LinearLayout body=Design.page(this,false,2,destination->{if(destination!=2)RecordUi.main(this,destination);});RecordUi.label(this,body);
        if(!failure.isEmpty()){RecordUi.header(body,"Sleep history",null);Design.space(body,24);Design.text(body,failure,15,400,Design.MUTED);Design.button(body,"Try again",true,this::load);return;}
        if(!loaded){RecordUi.header(body,"Sleep history",null);Design.space(body,24);Design.text(body,"Loading records…",15,400,Design.MUTED);return;}
        if(trends){trends(body);return;}
        LinearLayout header=RecordUi.header(body,"Sleep history",null);TextView trendAction=Design.text(this,"Trends",13,600,Design.BROWN);trendAction.setGravity(Gravity.CENTER);trendAction.setMinHeight(Design.dp(this,48));trendAction.setPadding(Design.dp(this,8),0,Design.dp(this,8),0);trendAction.setContentDescription("Trends");trendAction.setBackground(Design.touch(this,Color.TRANSPARENT,16));trendAction.setOnClickListener(v->{trends=true;render();});header.addView(trendAction);RecordUi.headerAction(header,searching?"close":"search","Search records",()->{searching=!searching;if(!searching)query="";render();});
        if(searching){EditText search=new EditText(this);search.setSingleLine();search.setTextSize(14*Appearance.scale(this));search.setTypeface(Design.font(this,400));search.setTextColor(Design.INK);search.setHintTextColor(Design.MUTED);search.setHint("Notes, tags or date");search.setContentDescription("Search notes and tags");search.setText(query);search.setBackground(Design.shape(this,Design.SOFT,12));Design.pad(search,12,8);body.addView(search,new LinearLayout.LayoutParams(-1,Design.dp(this,48)));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){query=s.toString();populate();}public void afterTextChanged(Editable e){}});}
        LinearLayout filters=Design.row(this);HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout choices=Design.row(this);scroll.addView(choices);filters.addView(scroll,new LinearLayout.LayoutParams(0,Design.dp(this,48),1));for(String name:new String[]{"All","Good sleep","Late night","Short"}){View chip=RecordUi.chip(this,name,filter.equals(name),()->{filter=name;render();});LinearLayout.LayoutParams chipSpace=new LinearLayout.LayoutParams(-2,Design.dp(this,48));chipSpace.rightMargin=Design.dp(this,4);choices.addView(chip,chipSpace);}View calendarAction=Design.iconButton(this,"calendar","Filter by date",this::chooseDay);calendarAction.setBackground(Design.touch(this,Design.SOFT,24));filters.addView(calendarAction,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(filters);
        helper=Design.text(body,"",11,400,Design.MUTED);list=Design.col(this);body.addView(list);populate();
    }
    private boolean matches(RecordEntry r){if(day!=null&&!r.day(cutoff()).equals(day))return false;if(filter.equals("Good sleep")&&(!r.edit.rated||r.edit.rating<4))return false;if(filter.equals("Late night")&&!RecordTrends.late(r,SleepPlans.load(this).bedtime))return false;if(filter.equals("Short")&&r.duration()>=goal())return false;String hay=r.edit.note+" "+String.join(" ",r.edit.tags)+" "+RecordUi.date(r.edit.end,r.zone())+" "+r.provenance();return hay.toLowerCase(Locale.ROOT).contains(query.trim().toLowerCase(Locale.ROOT));}
    private void populate(){if(list==null)return;list.removeAllViews();String definition=filter.equals("Good sleep")?"Your rested rating: 4–5.":filter.equals("Late night")?"Starts over 30 min after your bedtime goal.":filter.equals("Short")?"Duration below your saved goal.":"Recorded and user-reported periods.";helper.setVisibility(day==null&&filter.equals("All")?View.GONE:View.VISIBLE);helper.setText(day==null?definition:day.format(DateTimeFormatter.ofPattern("EEE d MMM",Locale.getDefault()))+" · "+definition);
        List<RecordEntry> shown=new ArrayList<>();for(RecordEntry record:records)if(matches(record))shown.add(record);shown.sort(Comparator.comparing((RecordEntry r)->r.day(cutoff())).reversed().thenComparing(Comparator.comparingLong((RecordEntry r)->r.edit.start).reversed()));
        if(shown.isEmpty()){monthHeader(list,day==null?"Your records":day.format(DateTimeFormatter.ofPattern("MMMM uuuu",Locale.getDefault())));Design.space(list,36);Design.text(list,records.isEmpty()?"No records yet":"No matching records",22,600,Design.INK);Design.space(list,10);Design.text(list,records.isEmpty()?"Track a night or add a sleep period you remember.":"Try another date, search or filter.",14,400,Design.MUTED);return;}
        String month="";for(RecordEntry r:shown){String next=r.day(cutoff()).format(DateTimeFormatter.ofPattern("MMMM uuuu",Locale.getDefault()));if(!next.equals(month)){month=next;monthHeader(list,month);}recordRow(list,r);}
    }
    private void monthHeader(LinearLayout body,String month){LinearLayout row=Design.row(this);row.addView(Design.text(this,month,15,600,Design.INK),new LinearLayout.LayoutParams(0,-2,1));TextView add=Design.text(this,"Add sleep  +",14,600,Design.INK);add.setGravity(Gravity.CENTER);add.setMinimumHeight(Design.dp(this,48));add.setContentDescription("Add sleep");add.setOnClickListener(v->open(0));row.addView(add);body.addView(row);}
    private void recordRow(LinearLayout body,RecordEntry r){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,70));Design.pad(row,5,9);if(selected==r.id||selected==0&&records.indexOf(r)==0)row.setBackground(Design.touch(this,Design.SOFT,14));else row.setBackground(Design.touch(this,Color.TRANSPARENT,14));
        LinearLayout date=Design.col(this);Design.text(date,r.day(cutoff()).format(DateTimeFormatter.ofPattern("EEE",Locale.getDefault())),14,600,Design.INK);Design.space(date,4);Design.text(date,r.day(cutoff()).format(DateTimeFormatter.ofPattern("d MMM",Locale.getDefault())),12,400,Design.MUTED);row.addView(date,new LinearLayout.LayoutParams(Design.dp(this,58),-2));
        LinearLayout middle=Design.col(this);middle.addView(new RecordRibbon(this,r,measurements.getOrDefault(r.id,List.of())),new LinearLayout.LayoutParams(-1,Design.dp(this,20)));Design.space(middle,4);LinearLayout times=Design.row(this);TextView start=Design.text(this,RecordUi.clock(this,r.edit.start,r.zone()),11,400,Design.MUTED),end=Design.text(this,RecordUi.clock(this,r.edit.end,r.zone()),11,400,Design.MUTED);start.setCompoundDrawables(RecordUi.glyph(this,"moon",Design.VIOLET,11),null,null,null);start.setCompoundDrawablePadding(Design.dp(this,3));end.setCompoundDrawables(RecordUi.glyph(this,"sun",Design.BROWN,11),null,null,null);end.setCompoundDrawablePadding(Design.dp(this,3));times.addView(start,new LinearLayout.LayoutParams(0,-2,1));end.setGravity(Gravity.START);times.addView(end,new LinearLayout.LayoutParams(0,-2,1));middle.addView(times);row.addView(middle,new LinearLayout.LayoutParams(0,-2,1));
        LinearLayout result=Design.col(this);result.setGravity(Gravity.END);TextView duration=Design.text(this,"",18,600,Design.INK);duration.setText(RecordUi.units(RecordUi.duration(r.duration())));result.addView(duration);String provenance=r.manual()?"Manual":r.edited?"Edited":r.interrupted==1?"Interrupted":"";if(!provenance.isEmpty()){Design.space(result,3);Design.text(result,provenance,10,400,Design.MUTED).setGravity(Gravity.END);}LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(Design.dp(this,88),-2);rp.leftMargin=Design.dp(this,10);row.addView(result,rp);Design.Icon arrow=new Design.Icon(this,"chevron",Design.INK);LinearLayout.LayoutParams arrowSpace=new LinearLayout.LayoutParams(Design.dp(this,18),Design.dp(this,18));arrowSpace.leftMargin=Design.dp(this,8);row.addView(arrow,arrowSpace);row.setContentDescription("Open record "+r.id+", "+r.day(cutoff())+", "+RecordUi.duration(r.duration())+", "+r.provenance());row.setOnClickListener(v->{selected=r.id;open(r.id);});body.addView(row);Design.line(body);
    }
    private void open(long id){startActivity(RecordUi.intent(this,RecordEditorActivity.class).putExtra("record",id));}
    private void chooseDay(){openCalendar("day",null);}
    private void openCalendar(String purpose,Bundle saved){if(calendar!=null)calendar.close();calendarPurpose=purpose;boolean filter=purpose.equals("day");calendar=new RecordCalendar(this,filter?"Records ending on":"Trend date",filter?(day==null?LocalDate.now():day):anchor,saved,value->{calendarPurpose=null;if(filter){day=value;populate();}else{anchorChosen=true;anchor=value;render();load();}},filter?()->{calendarPurpose=null;day=null;populate();}:null);}
    private void trends(LinearLayout body){LinearLayout header=RecordUi.header(body,"Trends",null);RecordUi.headerAction(header,"calendar","Sleep history",()->{trends=false;render();});header.getChildAt(header.getChildCount()-1).setBackground(Design.touch(this,Design.SOFT,24));RecordUi.headerAction(header,"more","Trend options",this::trendOptions);header.getChildAt(header.getChildCount()-1).setBackground(Design.touch(this,Design.SOFT,24));Design.space(body,6);RecordUi.segments(body,new String[]{"Week","Month","Year"},period,index->{period=index;render();});Design.space(body,16);
        RecordTrends.Range range=RecordTrends.range(anchor,period);SortedMap<LocalDate,RecordTrends.Day> days=RecordTrends.days(records,range,cutoff());boolean bankReady=bankSummaries!=null&&anchor.equals(bankAnchor);DatedGoalBank.Summary bank=bankReady?bankSummaries[period]:new DatedGoalBank.Summary();long deficit=-bank.balance;
        LinearLayout totals=Design.row(this),average=Design.col(this),gap=Design.col(this);Design.text(average,"Average duration",14,600,Design.INK);Design.space(average,6);TextView avg=Design.text(average,days.isEmpty()?"—":RecordUi.duration(RecordTrends.average(days.values())),48,700,Design.INK);avg.setText(RecordUi.units(avg.getText().toString()));totals.addView(average,new LinearLayout.LayoutParams(0,-2,1));View divider=new View(this);divider.setBackgroundColor(Design.LINE);LinearLayout.LayoutParams separator=new LinearLayout.LayoutParams(Design.dp(this,1),Design.dp(this,72));separator.setMargins(Design.dp(this,8),0,Design.dp(this,18),0);totals.addView(divider,separator);
        Design.text(gap,deficit<0?"Above goal":"Goal gap",12,400,Design.MUTED);Design.space(gap,7);long absoluteGap=Math.abs(deficit);String gapText=absoluteGap>=3600000L&&absoluteGap%3600000L==0?absoluteGap/3600000L+" h":RecordUi.duration(absoluteGap);TextView missing=Design.text(gap,bank.observed==0||!goalFailure.isEmpty()?"—":gapText,23,600,Design.INK);missing.setText(RecordUi.units(missing.getText().toString()));Design.space(gap,4);Design.text(gap,!bankReady?"Updating…":!goalFailure.isEmpty()?"Needs attention":!bank.hasDates()?"No dated goal":bank.observed+" recorded"+(bank.unknown>0?" · "+bank.unknown+" missing":""),11,400,Design.MUTED);gap.setMinimumHeight(Design.dp(this,72));gap.setContentDescription("Open dated goal bank. "+(bank.observed==0?"No recorded closed days":GoalProgress.signed(bank.balance))+". "+bank.observed+" recorded, "+bank.unknown+" missing.");gap.setBackground(Design.touch(this,android.graphics.Color.TRANSPARENT,12));gap.setOnClickListener(v->startActivity(RecordUi.intent(this,GoalBankActivity.class).putExtra("goal",bank.selected).putExtra("goalRangeStart",range.start.toString()).putExtra("goalRangeEnd",range.end.toString())));totals.addView(gap,new LinearLayout.LayoutParams(Design.dp(this,88),-2));body.addView(totals);
        trendHeading(body,period==2?"Monthly recorded duration":"Recorded duration");body.addView(new TrendsChart(this,days,range,period,false,goal()),new LinearLayout.LayoutParams(-1,Design.dp(this,158)));trendHeading(body,"Bedtime consistency");body.addView(new TrendsChart(this,days,range,period,true,goal()),new LinearLayout.LayoutParams(-1,Design.dp(this,118)));Design.space(body,8);
        if(!records.isEmpty()){RecordEntry latest=records.get(0);LinearLayout details=PlanActivity.detail(body,"report","Read details","Movement, room signals and notes",null,()->startActivity(RecordUi.intent(this,RecordReportActivity.class).putExtra("record",latest.id)));details.setContentDescription("Read details");View glyph=details.getChildAt(0);glyph.setPadding(Design.dp(this,10),Design.dp(this,10),Design.dp(this,10),Design.dp(this,10));glyph.setBackground(Design.shape(this,Design.SOFT,24));LinearLayout.LayoutParams disc=new LinearLayout.LayoutParams(Design.dp(this,46),Design.dp(this,46));disc.rightMargin=Design.dp(this,12);glyph.setLayoutParams(disc);}
        TextView rangeButton=Design.text(body,period==0?"Week ending "+anchor.format(DateTimeFormatter.ofPattern("d MMM uuuu",Locale.getDefault())):anchor.format(DateTimeFormatter.ofPattern(period==1?"MMMM uuuu":"uuuu",Locale.getDefault())),12,400,Design.MUTED);rangeButton.setMinHeight(Design.dp(this,40));rangeButton.setGravity(Gravity.CENTER_VERTICAL);rangeButton.setContentDescription("Choose trend date");rangeButton.setOnClickListener(v->chooseAnchor());
    }
    private void trendHeading(LinearLayout body,String title){Design.space(body,10);Design.text(body,title,16,600,Design.INK);Design.space(body,2);}
    private void trendOptions(){
        if(optionsDialog!=null)optionsDialog.dismiss();
        Dialog dialog=new Dialog(this);optionsDialog=dialog;dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);
        LinearLayout content=Design.col(this);Design.pad(content,20,20);content.setBackground(Design.shape(this,Design.CREAM,24));Design.text(content,"Trend options",22,600,Design.INK);Design.space(content,12);
        String[] names={"Choose dates","Day boundary","Sleep rhythm","About these charts"};String[] icons={"calendar","moon","report","info"};
        for(int i=0;i<names.length;i++){int action=i;PlanActivity.detail(content,icons[i],names[i],null,null,()->{dialog.dismiss();if(action==0)chooseAnchor();else if(action==1)chooseCutoff();else if(action==2)startActivity(RecordUi.intent(this,SleepRhythmActivity.class));else optionsDialog=SleepPicker.message(this,"Your recorded history","Duration excludes marked awake and paused time. Missing dates stay blank. Bedtime uses the longest main period of at least three hours. These are recorded times, not measured sleep stages.");});}
        Design.button(content,"Cancel",false,dialog::dismiss);ScrollView scroll=new ScrollView(this);scroll.addView(content);dialog.setContentView(scroll);dialog.show();Window window=dialog.getWindow();window.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),Design.dp(this,440)),-2);
    }
    private void chooseAnchor(){openCalendar("anchor",null);}
    private void chooseCutoff(){SleepPicker.time(this,"Day boundary",cutoff(),minutes->{Prefs.put(this,"statsCutoff",minutes);render();});}
    private final class CoverageStrip extends View {private final RecordEntry record;private final Paint p=new Paint(3);CoverageStrip(RecordEntry record){super(HistoryActivity.this);this.record=record;setContentDescription(record.manual()?"User-reported interval; no sensor measurements":"Recorded intervals; blank spaces are pauses or awake edits");}
        @Override protected void onDraw(Canvas c){super.onDraw(c);long span=Math.max(1,record.edit.end-record.edit.start);float top=getHeight()*.25f,bottom=getHeight()*.8f;p.setColor(0xffeee5f5);c.drawRoundRect(0,top,getWidth(),bottom,4,4,p);p.setColor(record.manual()?0xffc5a7ee:Design.VIOLET);for(RecordIntervals.Span s:record.coverage()){float a=getWidth()*(s.start-record.edit.start)/(float)span,b=getWidth()*(s.end-record.edit.start)/(float)span;c.drawRoundRect(a,top,b,bottom,4,4,p);}}
    }
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    void awaitReaders(long timeoutMs) throws Exception {if(worker.isShutdown()){if(!worker.awaitTermination(timeoutMs,TimeUnit.MILLISECONDS))throw new java.util.concurrent.TimeoutException("History readers still active");}else worker.submit(()->{}).get(timeoutMs,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){generation++;if(calendar!=null)calendar.close();if(optionsDialog!=null)optionsDialog.dismiss();worker.shutdownNow();super.onDestroy();}
}
